-- Seed: 小马AI API provider and model catalog
-- Source checked: https://api.lk888.ai/v1/skills/models?type=image|video|audio|chat on 2026-05-31.
-- The API Key is intentionally not stored here. Admin must configure it in the backend UI.

SET @xiaoma_provider_exists := (SELECT COUNT(*) FROM ai_model_providers WHERE provider_key = 'xiaoma' AND deleted_at IS NULL);

SELECT '小马AI', 'xiaoma', 'xiaoma', 'https://api.lk888.ai', '', 600, 3,
       '小马AI API。支持图片、视频、音频、聊天模型；媒体协议 /v1/media/generate + /v1/media/status，聊天模型按官方兼容协议透传。',
       'active', NOW(3)
WHERE @xiaoma_provider_exists = 0;

UPDATE ai_model_providers
   SET name = '小马AI',
       provider_type = 'xiaoma',
       api_base_url = IF(api_base_url IS NULL OR api_base_url = '', 'https://api.lk888.ai', api_base_url),
       default_timeout = GREATEST(default_timeout, 600),
       default_retry = IF(default_retry IS NULL OR default_retry = 0, 3, default_retry),
       remark = '小马AI API。支持图片、视频、音频、聊天模型；媒体协议 /v1/media/generate + /v1/media/status，聊天模型按官方兼容协议透传。',
       updated_at = NOW(3)
 WHERE provider_key = 'xiaoma' AND deleted_at IS NULL;

SET @xiaoma_id := (SELECT id FROM ai_model_providers WHERE provider_key = 'xiaoma' AND deleted_at IS NULL LIMIT 1);

DROP TEMPORARY TABLE IF EXISTS tmp_xiaoma_api_models;
CREATE TEMPORARY TABLE tmp_xiaoma_api_models (
  provider_id BIGINT UNSIGNED NOT NULL,
  name VARCHAR(64) NOT NULL,
  display_name VARCHAR(64) NOT NULL,
  model_type VARCHAR(16) NOT NULL,
  sub_type VARCHAR(32) NOT NULL,
  api_model_name VARCHAR(64) NOT NULL,
  upstream_model_code VARCHAR(64) NOT NULL,
  is_async TINYINT(1) NOT NULL,
  timeout_seconds INT NOT NULL,
  retry_times TINYINT NOT NULL,
  retry_delay_ms INT NOT NULL,
  daily_limit INT NOT NULL,
  daily_limit_per_user INT NOT NULL,
  max_concurrency INT NOT NULL,
  priority INT NOT NULL,
  points_cost INT NOT NULL,
  api_cost_cents INT NOT NULL,
  sort_order INT NOT NULL,
  config_json LONGTEXT NOT NULL,
  remark VARCHAR(255) NOT NULL,
  status VARCHAR(16) NOT NULL,
  PRIMARY KEY (provider_id, api_model_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


UPDATE ai_models m
JOIN tmp_xiaoma_api_models s
  ON s.provider_id = m.provider_id
 AND s.api_model_name COLLATE utf8mb4_unicode_ci = m.api_model_name COLLATE utf8mb4_unicode_ci
 AND m.deleted_at IS NULL
   SET m.name = s.name,
       m.display_name = s.display_name,
       m.model_type = s.model_type,
       m.sub_type = s.sub_type,
       m.upstream_model_code = s.upstream_model_code,
       m.is_async = s.is_async,
       m.timeout_seconds = s.timeout_seconds,
       m.retry_times = s.retry_times,
       m.retry_delay_ms = s.retry_delay_ms,
       m.max_concurrency = s.max_concurrency,
       m.sort_order = s.sort_order,
       m.config = s.config_json,
       m.remark = s.remark,
       m.updated_at = NOW(3);

SELECT s.provider_id, s.name, s.display_name, s.model_type, s.sub_type, s.api_model_name, s.upstream_model_code, s.is_async,
       '', '{}', '', '{}', '{}', s.timeout_seconds, s.retry_times, s.retry_delay_ms, s.daily_limit, s.daily_limit_per_user,
       s.max_concurrency, s.priority, s.points_cost, s.api_cost_cents, s.sort_order, s.config_json, s.remark, s.status, NOW(3), NOW(3)
  FROM tmp_xiaoma_api_models s
 WHERE NOT EXISTS (
   SELECT 1 FROM ai_models m
    WHERE m.provider_id = s.provider_id
      AND m.api_model_name COLLATE utf8mb4_unicode_ci = s.api_model_name COLLATE utf8mb4_unicode_ci
      AND m.deleted_at IS NULL
 );

DROP TEMPORARY TABLE IF EXISTS tmp_xiaoma_api_models;
